"""Starter module for the locked Toolformer loss-filter task."""

from __future__ import annotations

import numpy as np


def filter_api_calls(
    logp_with_result: np.ndarray,
    logp_call_only: np.ndarray,
    logp_no_call: np.ndarray,
    tau_filter: float,
) -> tuple[np.ndarray, np.ndarray]:
    """Return an ordered keep mask and one finite margin per proposed call."""

    # Validate inputs
    for mat, name in [(logp_with_result, 'logp_with_result'), (logp_call_only, 'logp_call_only'), (logp_no_call, 'logp_no_call')]:
        if not isinstance(mat, np.ndarray):
            raise ValueError(f'{name} must be a numpy array')
        if mat.ndim != 2:
            raise ValueError(f'{name} must be 2-dimensional')
        if mat.size == 0:
            raise ValueError(f'{name} must not be empty')
        if not np.isfinite(mat).all():
            raise ValueError(f'{name} contains non-finite values')
        if np.any(mat > 0):
            raise ValueError(f'{name} contains positive values')

    if not (logp_with_result.shape == logp_call_only.shape == logp_no_call.shape):
        raise ValueError('All input matrices must have the same shape')

    if isinstance(tau_filter, bool):
        raise ValueError('tau_filter must not be boolean')
    if not isinstance(tau_filter, (int, float, np.floating)):
        raise ValueError('tau_filter must be a numeric type')
    if not np.isfinite(tau_filter) or tau_filter < 0:
        raise ValueError('tau_filter must be finite and nonnegative')

    # Compute per-token best API-call log probability
    best_call = np.maximum(logp_with_result, logp_call_only)
    # Improvement over no_call
    improvement = best_call - logp_no_call
    # Total improvement per candidate (sum over future horizon)
    margins = np.sum(improvement, axis=1)
    # Keep candidates with margin above threshold
    keep = margins > tau_filter

    return keep, margins
